package com.aistock.scheduler.task;
import java.time.*;import java.util.*;import java.util.concurrent.*;import org.junit.jupiter.api.*;import com.aistock.common.BusinessException;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
@Tag("mysql") class RevisionScanMysqlTest {
 final TaskMysqlTest f=new TaskMysqlTest();TaskRepository tasks;RevisionScanRepository repo;final Instant now=Instant.parse("2026-10-05T14:00:00Z");final LocalDate cutoff=LocalDate.parse("2026-10-05");final String rule="origin-share-close-v1";
 void init(){tasks=f.repo();f.jdbc.update("delete from verification_revision_scan");repo=new RevisionScanRepository(f.jdbc,tasks);}
 RevisionClient.Event event(long id){return new RevisionClient.Event(id,"SH600030",UUID.randomUUID().toString());}
 PredictionTaskClient.Item item(String id){return new PredictionTaskClient.Item(id,"SH600030",cutoff,rule);}
 @Test void partialPageReplayRestartAndOldEventCannotSkip(){init();var c=repo.cursor(now);assertTrue(repo.begin(c,event(1),cutoff,now));var active=repo.cursor(now);String id="11111111-1111-1111-1111-111111111111";var page=new PredictionTaskClient.Page(cutoff,List.of(item(id)),id);assertTrue(repo.publish(active,page,now));assertFalse(repo.publish(active,page,now));var restarted=new RevisionScanRepository(f.jdbc,tasks);var saved=restarted.cursor(now);assertEquals(id,saved.afterId());assertEquals(0,saved.completedEventId());assertFalse(restarted.begin(saved,event(2),cutoff,now));assertTrue(restarted.publish(saved,new PredictionTaskClient.Page(cutoff,List.of(),null),now));assertEquals(1,restarted.cursor(now).completedEventId());assertEquals(1,tasks.list().size());assertEquals("PREDICTION_VERIFY",tasks.list().get(0).taskType());}
 @Test void malformedSecondItemRollsBackTasksAndCursor(){init();repo.begin(repo.cursor(now),event(1),cutoff,now);var active=repo.cursor(now);var good=item("11111111-1111-1111-1111-111111111111");var bad=new PredictionTaskClient.Item("22222222-2222-2222-2222-222222222222","SZ000002",cutoff,rule);assertThrows(RuntimeException.class,()->repo.publish(active,new PredictionTaskClient.Page(cutoff,List.of(good,bad),null),now));assertTrue(tasks.list().isEmpty());assertEquals(active,repo.cursor(now));}
 @Test void concurrentPublishCreatesOnlyOnePage()throws Exception{init();repo.begin(repo.cursor(now),event(3),cutoff,now);var c=repo.cursor(now);var p=new PredictionTaskClient.Page(cutoff,List.of(item(UUID.randomUUID().toString())),null);var pool=Executors.newFixedThreadPool(2);try{var a=pool.submit(()->repo.publish(c,p,now));var b=pool.submit(()->repo.publish(c,p,now));assertNotEquals(a.get(),b.get());assertEquals(1,tasks.list().size());assertEquals(3,repo.cursor(now).completedEventId());}finally{pool.shutdownNow();}}
 @Test void failureKeepsActiveEventAndResumesAtNewCutoff(){init();var client=mock(RevisionClient.class);when(client.next(0)).thenReturn(event(1));when(client.affected(anyString(),any(),any())).thenThrow(new RuntimeException());var plan=new RevisionVerificationPlan(repo,client,Clock.fixed(now,ZoneOffset.UTC),"private",false);assertFalse(plan.runOnce());var c=repo.cursor(now);assertEquals(cutoff,c.cutoffDate());assertEquals(0,c.completedEventId());assertNotNull(c.event());var recovered=new RevisionVerificationPlan(repo,client,Clock.fixed(now.plus(Duration.ofDays(2)),ZoneOffset.UTC),"private",false);doReturn(new PredictionTaskClient.Page(cutoff.plusDays(2),List.of(),null)).when(client).affected("SH600030",cutoff.plusDays(2),null);assertTrue(recovered.runOnce());assertEquals(1,repo.cursor(now).completedEventId());}
 @Test void controlledRecheckIsSeparateAndIdempotent(){init();String pred=UUID.randomUUID().toString();var req=UUID.randomUUID();var a=tasks.createRecheck(pred,"SH600030",cutoff,req,now);assertEquals(a.taskId(),tasks.createRecheck(pred,"SH600030",cutoff,req,now).taskId());assertNotEquals(a.taskId(),tasks.createRecheck(pred,"SH600030",cutoff,UUID.randomUUID(),now).taskId());assertThrows(BusinessException.class,()->tasks.createRecheck(pred,"SZ000002",cutoff,req,now));assertThrows(BusinessException.class,()->tasks.createRecheck(pred,"SH600030",cutoff,null,now));}
 @Test void staleActiveEventRestartsForNewCutoffWithoutKeyConflict(){init();repo.begin(repo.cursor(now),event(1),cutoff,now);var old=repo.cursor(now);String id="11111111-1111-1111-1111-111111111111";assertTrue(repo.publish(old,new PredictionTaskClient.Page(cutoff,List.of(item(id)),id),now));var oldPage=repo.cursor(now);Instant later=now.plus(Duration.ofDays(2));LocalDate today=cutoff.plusDays(2);var refreshed=repo.cursor(later);assertEquals(today,refreshed.cutoffDate());assertNull(refreshed.afterId());assertEquals(old.event(),refreshed.event());assertFalse(repo.publish(oldPage,new PredictionTaskClient.Page(cutoff,List.of(),null),later));var newest=new PredictionTaskClient.Item(id,"SH600030",today,rule);assertTrue(repo.publish(refreshed,new PredictionTaskClient.Page(today,List.of(newest),null),later));assertEquals(1,repo.cursor(later).completedEventId());assertEquals(2,tasks.list().size());}
 @Test void returnedEventUsesPostNetworkClockAndCrossedPageCannotCompleteOldDay(){init();Instant before=Instant.parse("2026-10-05T11:59:59Z");var time=new java.util.concurrent.atomic.AtomicReference<Instant>(before);Clock clock=new Clock(){public ZoneId getZone(){return ZoneOffset.UTC;}public Clock withZone(ZoneId z){return this;}public Instant instant(){return time.get();}};var client=mock(RevisionClient.class);when(client.next(0)).thenAnswer(inv->{time.set(now);return event(1);});when(client.affected("SH600030",cutoff,null)).thenReturn(new PredictionTaskClient.Page(cutoff,List.of(),null));assertTrue(new RevisionVerificationPlan(repo,client,clock,"private",false).runOnce());verify(client).affected("SH600030",cutoff,null);assertEquals(1,repo.cursor(now).completedEventId());var c=repo.cursor(now);repo.begin(c,event(2),cutoff,now);var active=repo.cursor(now);assertFalse(repo.publish(active,new PredictionTaskClient.Page(cutoff,List.of(),null),now.plus(Duration.ofDays(1))));assertEquals(1,repo.cursor(now).completedEventId());assertEquals(cutoff.plusDays(1),repo.cursor(now).cutoffDate());}
}
